// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/keys", wrapper.ListApiKeys)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/keys", wrapper.CreateApiKey)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/keys/{keyId}", wrapper.GetApiKey)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/keys/{keyId}", wrapper.UpdateApiKey)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/keys/{keyId}/disable", wrapper.DisableApiKey)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/keys/{keyId}/enable", wrapper.EnableApiKey)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/keys/{keyId}/revoke", wrapper.RevokeApiKey)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/models", wrapper.ListModels)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/models/{modelId}", wrapper.GetModel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/requests", wrapper.ListRequests)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/requests/{requestId}", wrapper.GetRequest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/usage/by-api-key", wrapper.ListUsageByApiKey)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/usage/by-model", wrapper.ListUsageByModel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/usage/summary", wrapper.GetUsageSummary)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/usage/timeline", wrapper.GetUsageTimeline)

	return m
}

